import { createSelector } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { initialState } from '.';

const selectSlice = (state: RootState) => state.common || initialState;

export const selectCommon = createSelector([selectSlice], state => state);
export const selectLoading = createSelector(
  [selectSlice],
  state => state.isLoading,
);
export const selectSettingsFocus = createSelector(
  [selectSlice],
  state => state.isSettingsFocused,
);
