import { Note } from 'app/services/NotesService/types';

import { getStaffStep } from './notation';

export type StaffClef = 'treble' | 'bass';

export const STAFF_CLEFS = {
  treble: { bottom: 'E4', top: 'F5', middle: 'B4' },
  bass: { bottom: 'G2', top: 'A3', middle: 'D3' },
} as const;

export const chooseStaffClef = (
  notes: Note[],
  previous: StaffClef = 'treble',
): StaffClef => {
  const ledgerCount = (clef: StaffClef) => {
    const bottom = getStaffStep(STAFF_CLEFS[clef].bottom);
    const top = getStaffStep(STAFF_CLEFS[clef].top);
    return notes.reduce((total, note) => {
      const step = getStaffStep(note);
      return total + Math.floor(Math.max(bottom - step, step - top, 0) / 2);
    }, 0);
  };
  const treble = ledgerCount('treble');
  const bass = ledgerCount('bass');
  // Preserve the previous clef for ties and rows without new noteheads.
  return bass === treble ? previous : bass < treble ? 'bass' : 'treble';
};
