import { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { DEFAULT_BPM } from 'app/services/MelodiesService/timing';
import { useCurrentMelody } from 'app/services/MelodiesService/useCurrentMelody';
import { selectNotes } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';

import { StaffLine } from './StaffLine';
import { layoutStaff } from './layout';

export const Staff = () => {
  const { melody: source } = useSelector(selectNotes);
  const melody = useCurrentMelody(source)!;
  const { isRecording } = useSelector(selectSettings);
  const [now, setNow] = useState(Date.now());
  const wrapper = useRef<HTMLDivElement>(null);
  const lastLine = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(900);
  const bpm = melody.bpm ?? DEFAULT_BPM;
  const lines = layoutStaff(melody, bpm, now, width);

  useEffect(() => {
    const element = wrapper.current;
    if (!element) return;
    const measure = () => {
      const measured = Math.floor(element.getBoundingClientRect().width);
      if (measured > 0) setWidth(measured);
    };
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? undefined
        : new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener('resize', measure);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, []);
  const hasHeldNotes = melody.notes.some(note => note.duration === undefined);

  useEffect(() => {
    if (!hasHeldNotes || !isRecording) return;
    const timer = window.setInterval(() => setNow(Date.now()), 50);
    return () => window.clearInterval(timer);
  }, [hasHeldNotes, isRecording]);

  useEffect(() => {
    if (isRecording) lastLine.current?.scrollIntoView?.({ block: 'center' });
  }, [lines.length, isRecording]);

  return (
    <StaffWrapper ref={wrapper}>
      {lines.map((line, index) => (
        <div
          key={index}
          ref={index === lines.length - 1 ? lastLine : undefined}
        >
          <StaffLine line={line} bpm={bpm} />
        </div>
      ))}
    </StaffWrapper>
  );
};

const StaffWrapper = styled.div`
  min-width: 0;
  width: 100%;
  color: ${p => p.theme.text};
  --staff-background: ${p => p.theme.background};
`;
