import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import {
  Tuning,
  centsBetween,
  nearestNote,
  nearestString,
  noteFrequency,
  tunings,
} from 'app/services/TunerService/pitch';
import { useTuner } from 'app/services/TunerService/useTuner';

import { HeaderIcon } from 'app/components/HeaderIcon';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

const formatCents = (cents: number) => {
  const value = Math.round(cents);
  const absolute = Math.abs(value);
  const ending =
    absolute % 100 >= 11 && absolute % 100 <= 14
      ? 'центов'
      : absolute % 10 === 1
      ? 'цент'
      : absolute % 10 >= 2 && absolute % 10 <= 4
      ? 'цента'
      : 'центов';
  return `${value > 0 ? '+' : ''}${value} ${ending}`;
};

export const TunerPage = () => {
  const tuner = useTuner();
  const [tuning, setTuning] = useState<Tuning>('standard');
  const [selected, setSelected] = useState<number | null>(null);
  const listening = tuner.status === 'listening';
  const frequency = tuner.frequency;
  const active =
    selected ?? (frequency ? nearestString(frequency, tuning) : null);
  const target = active === null ? null : tunings[tuning].notes[active];
  const cents =
    frequency && target ? centsBetween(frequency, noteFrequency(target)) : null;
  const inTune = cents !== null && Math.abs(cents) <= 5;
  const position =
    cents === null ? 50 : 50 + Math.max(-50, Math.min(50, cents));
  const message = !listening
    ? 'Готов к настройке'
    : cents === null
    ? 'Сыграйте одну открытую струну'
    : inTune
    ? 'Струна настроена'
    : cents < 0
    ? 'Подтяните струну'
    : 'Ослабьте струну';

  return (
    <PageWrapper aria-label="Гитарный тюнер">
      <Helmet>
        <title>Гитарный тюнер</title>
      </Helmet>
      <Layout>
        <Heading>
          <Eyebrow>
            <HeaderIcon name="tuner" /> ГИТАРНЫЙ ТЮНЕР
          </Eyebrow>
          <h1>Каждая струна на своём месте</h1>
          <p>
            Настройте шестиструнную гитару через микрофон или аудиоинтерфейс.
          </p>
        </Heading>
        <InputPanel aria-label="Аудиовход тюнера">
          <InputFields>
            <Field>
              Аудиовход
              <select
                value={tuner.deviceId}
                disabled={!tuner.supported || tuner.status === 'connecting'}
                onChange={event => tuner.selectDevice(event.target.value)}
              >
                <option value="">Микрофон по умолчанию</option>
                {tuner.deviceId &&
                  !tuner.devices.some(
                    device => device.deviceId === tuner.deviceId,
                  ) && (
                    <option value={tuner.deviceId}>Выбранный аудиовход</option>
                  )}
                {tuner.devices
                  .filter(device => device.deviceId)
                  .map((device, index) => (
                    <option key={device.deviceId} value={device.deviceId}>
                      {device.label || `Аудиовход ${index + 1}`}
                    </option>
                  ))}
              </select>
            </Field>
            {listening && tuner.channels > 1 && (
              <Field>
                Канал
                <select
                  value={tuner.channel}
                  onChange={event =>
                    tuner.selectChannel(Number(event.target.value))
                  }
                >
                  {Array.from({ length: tuner.channels }, (_, index) => (
                    <option key={index} value={index}>
                      Вход {index + 1}
                    </option>
                  ))}
                </select>
              </Field>
            )}
            <Start
              type="button"
              disabled={!tuner.supported}
              onClick={() =>
                tuner.status === 'idle' ? void tuner.start() : tuner.stop()
              }
            >
              {tuner.status === 'connecting'
                ? 'Отменить подключение'
                : listening
                ? 'Выключить тюнер'
                : 'Включить микрофон'}
            </Start>
          </InputFields>
          <LevelRow>
            <span>{listening ? 'Уровень входа' : 'Микрофон выключен'}</span>
            <progress
              aria-label="Уровень аудиовхода"
              max={1}
              value={tuner.level}
            />
          </LevelRow>
          {tuner.clipping && (
            <Warning role="status">
              Сигнал перегружен. Уменьшите усиление аудиовхода.
            </Warning>
          )}
          {tuner.error && (
            <ErrorMessage role="alert">{tuner.error}</ErrorMessage>
          )}
          {!tuner.supported && (
            <ErrorMessage role="alert">
              Для тюнера нужен браузер с доступом к микрофону и Web Audio.
              Откройте приложение по HTTPS или на localhost.
            </ErrorMessage>
          )}
          <Privacy>
            Звук анализируется на вашем устройстве, не записывается и не
            отправляется на сервер.
          </Privacy>
        </InputPanel>
        <Panel>
          <Settings>
            <Field>
              Строй гитары
              <select
                value={tuning}
                onChange={event => setTuning(event.target.value as Tuning)}
              >
                {Object.entries(tunings).map(([id, value]) => (
                  <option key={id} value={id}>
                    {value.label}
                  </option>
                ))}
              </select>
            </Field>
            <Mode>
              <span>Выбор струны</span>
              <ModeButtons aria-label="Выбор струны">
                <button
                  type="button"
                  aria-pressed={selected === null}
                  onClick={() => setSelected(null)}
                >
                  Авто
                </button>
                <button
                  type="button"
                  aria-pressed={selected !== null}
                  onClick={() => setSelected(active ?? 0)}
                >
                  Вручную
                </button>
              </ModeButtons>
            </Mode>
            <Reference>
              Эталон <strong>A4 = 440 Гц</strong>
            </Reference>
          </Settings>

          <Display $inTune={inTune}>
            <NoteLabel>
              {target
                ? `${6 - active!}-я струна · цель ${target}`
                : listening
                ? 'Слушаем открытую струну'
                : `${tunings[tuning].label} · 6 струн`}
            </NoteLabel>
            <Note aria-label="Распознанная нота">
              {frequency
                ? nearestNote(frequency).slice(0, -1)
                : target?.slice(0, -1) ?? '—'}
              <small>
                {frequency
                  ? nearestNote(frequency).slice(-1)
                  : target?.slice(-1)}
              </small>
            </Note>
            <Frequency>
              {frequency
                ? `${frequency.toFixed(1)} Гц`
                : 'Частота появится здесь'}
            </Frequency>
            <Gauge
              role="meter"
              aria-label="Отклонение от ноты"
              aria-valuemin={-50}
              aria-valuemax={50}
              aria-valuenow={
                cents === null
                  ? 0
                  : Math.max(-50, Math.min(50, Math.round(cents)))
              }
              aria-valuetext={
                cents === null
                  ? 'Нет сигнала'
                  : `${formatCents(cents)}. ${message}`
              }
            >
              <Ticks aria-hidden="true">
                {Array.from({ length: 21 }, (_, index) => (
                  <i key={index} />
                ))}
              </Ticks>
              <Center aria-hidden="true" />
              {cents !== null && (
                <Needle aria-hidden="true" style={{ left: `${position}%` }} />
              )}
            </Gauge>
            <Scale aria-hidden="true">
              <span>−50</span>
              <span>0</span>
              <span>+50</span>
            </Scale>
            <Feedback role="status" aria-live="polite">
              {message}
            </Feedback>
            <Cents>
              {cents === null
                ? 'Отклонение в центах'
                : `${formatCents(cents)}${inTune ? ' · точно' : ''}`}
            </Cents>
          </Display>

          <Strings aria-label="Струны гитары">
            {tunings[tuning].notes.map((note, index) => (
              <StringButton
                key={index}
                type="button"
                aria-label={`${6 - index}-я струна ${note}`}
                aria-pressed={active === index}
                $inTune={active === index && inTune}
                onClick={() => setSelected(index)}
              >
                <span>{6 - index}</span>
                <strong>
                  {note.slice(0, -1)}
                  <small>{note.slice(-1)}</small>
                </strong>
                <span>
                  {noteFrequency(note).toFixed(1)}
                  <span className="unit"> Гц</span>
                </span>
              </StringButton>
            ))}
          </Strings>
          <StringHint>
            От толстой струны к тонкой. Нажмите на струну для ручной настройки.
          </StringHint>
        </Panel>

        <Help>
          <h2>Как настроить гитару</h2>
          <ol>
            <li>Включите микрофон и разрешите доступ в браузере.</li>
            <li>
              Сыграйте открытую струну и приглушите остальные. В режиме «Авто»
              тюнер выберет ближайшую струну.
            </li>
            <li>
              Поворачивайте колок, пока указатель не окажется в центре. Для
              сильно расстроенной гитары выберите струну вручную.
            </li>
          </ol>
          <p>
            Настраивайте в тихом месте. Остановите метроном, драм-машину и
            воспроизведение, чтобы тюнер слышал только гитару.
          </p>
        </Help>
      </Layout>
    </PageWrapper>
  );
};

