import {
  InstrumentEffects,
  defaultEffects,
  effectDefinitions,
  effectNames,
  normalizeEffects,
} from './settings';

export interface EffectPreset {
  id: string;
  name: string;
  description?: string;
  settings: InstrumentEffects;
}

const preset = (
  id: string,
  name: string,
  description: string,
  effects: Partial<InstrumentEffects>,
): EffectPreset => ({
  id,
  name,
  description,
  settings: { ...defaultEffects(''), ...effects },
});

