import {
  TimeSignature,
  getBeatsPerMeasure,
  getTimeSignature,
} from 'app/services/MelodiesService/meter';
import { Melody } from 'app/services/MelodiesService/types';

import { layoutChord } from './chordLayout';
import { StaffClef, chooseStaffClef } from './clefs';
import { StaffChord, StaffEvent, groupStaffNotes } from './notation';

const LEFT = 70;
const RIGHT = 20;
const PIXELS_PER_BEAT = 80;

export type PositionedChord = StaffChord & { x: number };
export type DurationSegment = {
  event: StaffEvent;
  from: number;
  to: number;
  continued: boolean;
  continues: boolean;
};
export type StaffSystem = {
  width: number;
  clef: StaffClef;
  timeSignature: TimeSignature;
  measureNumber: number;
  continuesMeasure: boolean;
  barLines: { x: number; number: number }[];
  closingBar?: { x: number; final: boolean };
  groups: PositionedChord[];
  durations: DurationSegment[];
  beats: { x: number; number: number }[];
};

const accidentalWidth = (group: StaffChord) =>
  Math.max(
    0,
    ...group.notes.map(note =>
      note.accidental ? (note.accidentalColumn + 1) * 13 : 0,
    ),
  );

// Bar lines and attacks are distinct anchors: an attack on a downbeat sits
// after the bar, while a release at that time ends exactly at the bar.
export const layoutStaff = (
  melody: Melody,
  bpm: number,
  now: number,
  availableWidth: number,
): StaffSystem[] => {
  const beat = 60000 / bpm;
  const timeSignature = getTimeSignature(melody.timeSignature);
  const left = timeSignature.startsWith('12/') ? LEFT + 14 : LEFT;
  const [beatsPerMeasure, unit] = timeSignature.split('/').map(Number);
  const countDuration = beat * (4 / unit);
  const measureDuration = getBeatsPerMeasure(timeSignature) * beat;
  const groups = groupStaffNotes(melody.notes, measureDuration);
  if (!groups.length) return [];
  const durationOf = (event: StaffEvent | Melody['notes'][number]) =>
    event.duration ??
    Math.max(1, now - (melody.firstStart ?? now) - event.start);
  const endTime = Math.max(
    ...melody.notes.map(event => event.start + durationOf(event)),
  );
  const measureCount = Math.max(
    1,
    Math.ceil(endTime / measureDuration),
    Math.floor(groups[groups.length - 1].start / measureDuration) + 1,
  );
  const measures = Array.from({ length: measureCount }, () => [] as number[]);
  groups.forEach((group, index) => {
    measures[Math.floor(group.start / measureDuration)].push(index);
  });
  const spaces = groups.map(group => ({
    before: accidentalWidth(group) + 24,
    after: Math.max(
      Math.max(...group.notes.map(note => note.headOffset)) + 24,
      layoutChord(group, bpm, 'treble').right + 12,
      layoutChord(group, bpm, 'bass').right + 12,
    ),
  }));
  const minimumWidths = measures.map(indexes =>
    indexes.reduce(
      (total, index) => total + spaces[index].before + spaces[index].after + 12,
      12,
    ),
  );
  const width = Math.max(
    availableWidth,
    left +
      RIGHT +
      Math.max(...spaces.map(space => space.before + space.after)) +
      12,
  );
  const capacity = width - left - RIGHT;
  const minimumMeasureWidth = Math.max(...minimumWidths);
  const preferredMeasureWidth = Math.max(
    minimumMeasureWidth,
    (measureDuration / beat) * PIXELS_PER_BEAT,
  );
  const measuresPerLine = Math.min(
    measureCount,
    Math.max(1, Math.floor(capacity / preferredMeasureWidth)),
  );
  const measureWidth = Math.max(
    minimumMeasureWidth,
    capacity / measuresPerLine,
  );
  const bars = Array.from({ length: measureCount + 1 }, (_, index) => ({
    time: index * measureDuration,
    x: index * measureWidth,
    number: index + 1,
  }));
  const positions: number[] = [];
  const bounds: { left: number; right: number }[] = [];
  const anchors: { time: number; x: number }[] = [];
  measures.forEach((indexes, measureIndex) => {
    const bar = bars[measureIndex];
    anchors.push({ time: bar.time, x: bar.x });
    let reserved = 0;
    const free = measureWidth - minimumWidths[measureIndex];
    indexes.forEach(index => {
      const group = groups[index];
      const { before, after } = spaces[index];
      reserved += 12 + before;
      // Reserve symbol space first; distribute the remaining space by time.
      const x =
        bar.x + reserved + ((group.start - bar.time) / measureDuration) * free;
      positions[index] = x;
      bounds[index] = { left: x - before, right: x + after };
      reserved += after;
      anchors.push({ time: group.start, x });
    });
  });
  anchors.push(bars[bars.length - 1]);
  const timeX = (time: number) => {
    const exactBar = bars.find(bar => bar.time === time);
    if (exactBar) return exactBar.x;
    const next = anchors.findIndex(anchor => anchor.time > time);
    const index = next === -1 ? anchors.length - 1 : next - 1;
    if (index < 0)
      return anchors[0].x + ((time - anchors[0].time) / beat) * PIXELS_PER_BEAT;
    if (index === anchors.length - 1)
      return (
        anchors[index].x +
        ((time - anchors[index].time) / beat) * PIXELS_PER_BEAT
      );
    return (
      anchors[index].x +
      ((time - anchors[index].time) /
        (anchors[index + 1].time - anchors[index].time)) *
        (anchors[index + 1].x - anchors[index].x)
    );
  };
  const durations = groups.flatMap((group, index) =>
    group.notes.map(event => {
      const from = positions[index] + 8 + event.headOffset;
      return {
        event,
        from,
        to: Math.max(from + 1, timeX(event.start + durationOf(event))),
      };
    }),
  );
  const beats = Array.from(
    { length: Math.ceil(endTime / countDuration) },
    (_, index) => ({
      x: timeX(index * countDuration),
      number: (index % beatsPerMeasure) + 1,
    }),
  );
  const end = measureCount * measureWidth;
  const complete = melody.notes.every(event => event.duration !== undefined);
  const lines: StaffSystem[] = [];
  let clef: StaffClef = 'treble';
  let start = 0;
  while (start < end) {
    const lineStart = start;
    let stop = Math.min(lineStart + capacity, end);
    if (stop < end) {
      const fittingBars = bars.filter(
        bar => bar.x > lineStart && bar.x <= stop,
      );
      if (fittingBars.length) stop = fittingBars[fittingBars.length - 1].x;
    }
    const crossing = bounds.find(
      bound => bound.left < stop && bound.right > stop,
    );
    if (crossing && crossing.left > lineStart) stop = crossing.left;
    const localX = (x: number) => left + x - lineStart;
    const owningBar = bars.filter(bar => bar.x <= lineStart).slice(-1)[0];
    const final = stop === end && complete;
    const lineGroups = groups.flatMap((group, index) =>
      positions[index] >= lineStart && positions[index] < stop
        ? [{ ...group, x: localX(positions[index]) }]
        : [],
    );
    clef = chooseStaffClef(
      lineGroups.flatMap(group => group.notes.map(event => event.note)),
      clef,
    );
    lines.push({
      width,
      clef,
      timeSignature,
      measureNumber: owningBar.number,
      continuesMeasure: lineStart > owningBar.x,
      barLines: bars
        .filter(bar => bar.x >= lineStart && bar.x < stop)
        .map(bar => ({ x: localX(bar.x), number: bar.number })),
      closingBar:
        final || bars.some(bar => bar.x === stop)
          ? { x: localX(stop), final }
          : undefined,
      groups: lineGroups,
      // [lineStart, stop): a release exactly at the boundary has no continuation.
      durations: durations
        .filter(duration => duration.from < stop && duration.to > lineStart)
        .map(duration => ({
          ...duration,
          from: localX(Math.max(lineStart, duration.from)),
          to: localX(Math.min(stop, duration.to)),
          continued: duration.from < lineStart,
          continues: duration.to > stop,
        })),
      beats: beats
        .filter(tick => tick.x >= lineStart && tick.x < stop)
        .map(tick => ({ ...tick, x: localX(tick.x) })),
    });
    start = stop;
  }
  return lines;
};
